parameters.jsCode:
// VALIDATION DÉFENSIVE & ASSURANCE D'IDEMPOTENCE
const ocrResult = $input.item.json || {};
const classifierNode = $('2. Classifier Intention (IA / NLP)').item.json || {};
const emailNode = $('1. E-mail Entrant (Trigger Webhook / Clic)').item.json || {};

const body = emailNode.body || {};
const emailSender = (classifierNode.email_expediteur || ocrResult.contact?.email || body.sender || body.from || 'candidat@example.local').toLowerCase().trim();
const emailSubject = classifierNode.sujet || body.subject || emailNode.subject || 'Candidature par email';
const emailContent = body.content || body.text || emailNode.content || 'Bonjour, je vous soumets ma candidature.';

// Dérivation d'un Message-ID universel pour garantir l'idempotence stricte (anti-doublon)
const emailMessageId = body.message_id || body.messageId || emailNode.headers?.['message-id'] || `<msg-${Date.now()}-${Math.random().toString(36).substr(2, 9)}@alpaciment.local>`;

// Fonction de normalisation des dates ISO (YYYY-MM-DD)
function sanitizeIsoDate(val) {
  if (!val) return null;
  const str = String(val).trim();
  // Vérifie si déjà au format YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) return str;
  // Si année seule (ex: 2023)
  if (/^\d{4}$/.test(str)) return `${str}-01-01`;
  // Tentative parsing Date standard
  const d = new Date(str);
  if (!isNaN(d.getTime())) {
    return d.toISOString().split('T')[0];
  }
  return null;
}

// Sanitization des listes
const sanitizedCompetences = (ocrResult.competences || []).filter(c => c && c.nom).map(c => ({
  nom: String(c.nom).trim(),
  niveau: c.niveau || 'Intermédiaire'
}));

const sanitizedExperiences = (ocrResult.experiences || []).filter(e => e && e.poste).map(e => ({
  poste: String(e.poste).trim(),
  entreprise: String(e.entreprise || '').trim(),
  date_debut: sanitizeIsoDate(e.date_debut),
  date_fin: sanitizeIsoDate(e.date_fin),
  description: e.description ? String(e.description).trim() : null
}));

const sanitizedProjets = (ocrResult.projets || []).filter(p => p && p.titre_projet).map(p => ({
  titre_projet: String(p.titre_projet).trim(),
  role: p.role ? String(p.role).trim() : null,
  technologies: p.technologies ? String(p.technologies).trim() : null,
  url_projet: p.url_projet ? String(p.url_projet).trim() : null,
  date_debut: sanitizeIsoDate(p.date_debut),
  date_fin: sanitizeIsoDate(p.date_fin),
  description: p.description ? String(p.description).trim() : null
}));

const sanitizedFormations = (ocrResult.formations || []).filter(f => f && f.diplome).map(f => ({
  diplome: String(f.diplome).trim(),
  etablissement: String(f.etablissement || '').trim(),
  date_obtention: sanitizeIsoDate(f.date_obtention || f.annee_obtention),
  domaine_etude: f.domaine_etude ? String(f.domaine_etude).trim() : null
}));

return {
  json: {
    cle_idempotence: emailMessageId,
    email_message_id: emailMessageId,
    nom: (ocrResult.contact?.nom || 'Candidat').trim(),
    prenom: (ocrResult.contact?.prenom || '').trim(),
    nom_complet: (ocrResult.contact?.nom_complet || 'Candidat').trim(),
    email: emailSender,
    telephone: ocrResult.contact?.telephone || null,
    ville: ocrResult.contact?.ville || null,
    id_offre: classifierNode.id_offre || null,
    source: 'email / n8n',
    sujet_email: emailSubject,
    corps_email: emailContent,
    message_motivation: emailContent,
    texte_brut_ocr: ocrResult.texte_brut_ocr || null,
    donnees_json: {
      contact: ocrResult.contact || {},
      competences: sanitizedCompetences,
      experiences: sanitizedExperiences,
      projets: sanitizedProjets,
      formations: sanitizedFormations
    }
  }
};

